  "vulnerabilidade_identificada": "Possibilidade de ReDoS por construção de expressões regulares com o valor variável challengeKey.",
  "causa_da_vulnerabilidade": "challengeKey é interpolado diretamente em padrões RegExp. Embora seja obtido de marcadores nos arquivos de snippets, caracteres especiais nele são interpretados como sintaxe de regex e podem produzir padrões com comportamento de backtracking excessivo.",
  "estrategia_de_correcao": "Escapar os metacaracteres de challengeKey antes de interpolá-lo nas expressões regulares, preservando a correspondência literal do identificador e o comportamento de seleção dos snippets.",
  "edicoes": [
    {
      "arquivo": "lib/codingChallenges.ts",
      "trecho_original": "function getCodingChallengeFromFileContent (source: string, challengeKey: string) {\n  const snippets = source.match(`[/#]{0,2} vuln-code-snippet start.*${challengeKey}([^])*vuln-code-snippet end.*${challengeKey}`)",
      "trecho_corrigido": "function getCodingChallengeFromFileContent (source: string, challengeKey: string) {\n  const escapedChallengeKey = challengeKey.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n  const snippets = source.match(`[/#]{0,2} vuln-code-snippet start.*${escapedChallengeKey}([^])*vuln-code-snippet end.*${escapedChallengeKey}`)"
    },
